/**
 * Command of Evidence: Textual (coet), research questions, rewritten to the Stellify question standard.
 * Every passage reports a real, published study, checked against its record (PubMed or Crossref) on the date in
 * meta.source; "if true" choices are hypothetical findings, as on the SAT, and are written so exactly one bears on
 * the claim in the direction asked.
 */
import type { RawQuestion } from '@/lib/types';
import type { TrapCode } from '../distractors';

const CHECKED = '2026-11-27';
const src = (cite: string, url: string) => ({ cite, url, checked: CHECKED });
const review = (teacher: string) => ({
  teacher: `AI teacher pass (Stellify): ${teacher}`,
  bias: 'AI bias and clarity pass (Stellify): the topic is explained inside the passage, no outside knowledge or cultural, regional or income assumptions are needed, and the wording has no double negatives.',
  date: CHECKED,
});
type Q = RawQuestion & { tags: (TrapCode | null)[] };

